CREATE TABLE public.login_profiles (login_id uuid NOT NULL, profile_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(login_id,profile_id), UNIQUE(profile_id));
GRANT SELECT ON public.login_profiles TO authenticated;
GRANT ALL ON public.login_profiles TO service_role;
ALTER TABLE public.login_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_login_profiles ON public.login_profiles FOR SELECT TO authenticated USING(login_id=auth.uid());
CREATE TRIGGER login_profiles_updated BEFORE UPDATE ON public.login_profiles FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
INSERT INTO public.login_profiles(login_id,profile_id) SELECT user_id,user_id FROM public.profiles;
CREATE TABLE public.profile_sessions (login_id uuid NOT NULL, session_id text NOT NULL, profile_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(login_id,session_id));
GRANT SELECT ON public.profile_sessions TO authenticated;
GRANT ALL ON public.profile_sessions TO service_role;
ALTER TABLE public.profile_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_session ON public.profile_sessions FOR SELECT TO authenticated USING(login_id=auth.uid() AND session_id=auth.jwt()->>'session_id');
CREATE TRIGGER profile_sessions_updated BEFORE UPDATE ON public.profile_sessions FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE OR REPLACE FUNCTION public.active_profile_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT lp.profile_id FROM public.login_profiles lp JOIN public.profiles p ON p.user_id=lp.profile_id LEFT JOIN public.profile_sessions s ON s.login_id=lp.login_id AND s.session_id=auth.jwt()->>'session_id' WHERE lp.login_id=auth.uid() AND p.active AND lp.profile_id=coalesce(s.profile_id,auth.uid()) LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.active_profile_id() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.active_profile_id() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.switch_my_profile(target_profile uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR auth.jwt()->>'session_id' IS NULL THEN RAISE EXCEPTION 'Sessão inválida'; END IF; IF NOT EXISTS(SELECT 1 FROM public.login_profiles l JOIN public.profiles p ON p.user_id=l.profile_id JOIN public.user_roles r ON r.user_id=p.user_id WHERE l.login_id=auth.uid() AND l.profile_id=target_profile AND p.active AND r.role IN ('director','master','representative','supervisor')) THEN RAISE EXCEPTION 'Perfil não autorizado ou inativo'; END IF; INSERT INTO public.profile_sessions(login_id,session_id,profile_id) VALUES(auth.uid(),auth.jwt()->>'session_id',target_profile) ON CONFLICT(login_id,session_id) DO UPDATE SET profile_id=EXCLUDED.profile_id,updated_at=now(); INSERT INTO public.access_audit(actor_id,target_user_id,action,details) VALUES(auth.uid(),target_profile,'PROFILE_SWITCHED','{}'); RETURN target_profile; END $$;
REVOKE ALL ON FUNCTION public.switch_my_profile(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.switch_my_profile(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.my_linked_profiles() RETURNS TABLE(profile_id uuid,full_name text,role public.app_role,management_name text,company_name text,team text,active boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.user_id,p.full_name,r.role,p.management_name,p.company_name,p.team,p.active FROM public.login_profiles l JOIN public.profiles p ON p.user_id=l.profile_id JOIN public.user_roles r ON r.user_id=p.user_id WHERE l.login_id=auth.uid() ORDER BY p.created_at,p.user_id $$;
REVOKE ALL ON FUNCTION public.my_linked_profiles() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.my_linked_profiles() TO authenticated;
DO $$ DECLARE pol record; u text; c text; BEGIN FOR pol IN SELECT * FROM pg_policies WHERE schemaname='public' AND tablename IN ('profiles','user_roles','sales','goals','access_audit','admin_invites','tv_sales_feed') LOOP u:=replace(pol.qual,'auth.uid()','public.active_profile_id()'); c:=replace(pol.with_check,'auth.uid()','public.active_profile_id()'); EXECUTE format('ALTER POLICY %I ON public.%I %s %s',pol.policyname,pol.tablename,CASE WHEN u IS NOT NULL THEN 'USING ('||u||')' ELSE '' END,CASE WHEN c IS NOT NULL THEN 'WITH CHECK ('||c||')' ELSE '' END); END LOOP; END $$;
CREATE OR REPLACE FUNCTION private.is_in_my_structure(_viewer uuid,_target uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH RECURSIVE descendants AS (SELECT p.user_id FROM public.profiles p WHERE p.user_id=_viewer UNION SELECT p.user_id FROM public.profiles p JOIN descendants d ON p.manager_id=d.user_id) SELECT EXISTS(SELECT 1 FROM descendants WHERE user_id=_target) $$;
ALTER POLICY authenticated_view_company_logos ON storage.objects USING (bucket_id='company-logos' AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.user_id::text=(storage.foldername(objects.name))[1] AND (p.user_id=public.active_profile_id() OR private.has_role(public.active_profile_id(),'director') OR private.is_in_my_structure(public.active_profile_id(),p.user_id))));